import java.util.List;
import java.util.ArrayList;

// Simulate Eclipse UI API
class MyListSelectionDialog {
    public void setInitialSelections(Object[] initialSelections) {
        System.out.println("Set selections: " + initialSelections.length);
    }
    public void setInitialSelections(List<String> initialSelections) {
        System.out.println("Set selections: " + initialSelections.size());
    }
}

interface MyResource {}
class ConcreteResource implements MyResource {}

public class TestClass {
    public void method() {
        MyListSelectionDialog lsd = new MyListSelectionDialog();
        List<String> names = new ArrayList<>();
        lsd.setInitialSelections(names); // Argument is List, not an array. Should not match.

        ConcreteResource[] alreadyCastResources = new ConcreteResource[2];
        lsd.setInitialSelections((java.lang.Object[]) alreadyCastResources); // Already has the cast. Should not match.
    }
}

